```json
{
  "root_causes": [
    {
      "service": "checkout",
      "fault_kind": "http_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n FROM abnormal_traces WHERE service_name='checkout' AND attr_span_kind='Server' GROUP BY 1,2,3", "claim": "Checkout has zero server spans in the abnormal window; PlaceOrder requests never complete (3 in normal)."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, round(duration/1e6,1) ms, attr_status_code FROM abnormal_traces WHERE trace_id LIKE '598b03ce%' ORDER BY time", "claim": "Checkout's trace stops after GetCart and GetProduct; no shipping or quote call follows before frontend times out at 15 s."},
        {"kind": "log", "sql": "SELECT 'abn' p, count(*) n FROM abnormal_logs WHERE service_name='shipping' AND message='Requesting quote' UNION ALL SELECT 'norm', count(*) FROM normal_logs WHERE service_name='shipping' AND message='Requesting quote'", "claim": "Shipping logs 'Requesting quote' 5 times in normal and 0 times in abnormal, so checkout's quote request never arrives."},
        {"kind": "trace", "sql": "SELECT service_name, count(*) n FROM abnormal_traces WHERE service_name IN ('quote','currency','payment') GROUP BY 1 UNION ALL SELECT 'quote_norm', count(*) FROM normal_traces WHERE service_name='quote'", "claim": "Quote has no spans in the abnormal window (27 in normal); currency and payment spans also drop out downstream of checkout's quote step."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, attr_http_response_status_code, count(*) n, round(avg(duration)/1e6,1) ms FROM abnormal_traces WHERE service_name='frontend-proxy' AND attr_http_response_status_code=504 GROUP BY ALL", "claim": "Frontend-proxy returns 504 after about 15 s on checkout requests, showing the stall surfaces to users."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "checkout",
      "to": "frontend",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, round(duration/1e6,1) ms, attr_status_code FROM abnormal_traces WHERE trace_id LIKE '598b03ce%' ORDER BY time", "claim": "Frontend POST waits about 15 s on checkout's PlaceOrder, which never completes in this trace."}
      ]
    },
    {
      "from": "frontend",
      "to": "frontend-proxy",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, round(duration/1e6,1) ms, attr_http_response_status_code FROM abnormal_traces WHERE trace_id LIKE '598b03ce%' ORDER BY time", "claim": "The same trace shows frontend-proxy ingress returning 504 at about 15 s, matching the frontend's stalled POST."}
      ]
    }
  ]
}
